<script setup>
import {onMounted,onUnmounted,ref,watch} from 'vue';
const props=defineProps({progress:Number,reduced:Boolean,pointer:Object});
const root=ref(null),canvas=ref(null),ready=ref(false),dragging=ref(false);
let renderer,scene,camera,model,THREE,frame=0,resize,intersection,visible=true,destroyed=false,last=0,environment;
let drag=null,yaw=-.23,pitch=.06,hover=0,visorHover=0,raycaster,screenPoint;
const smooth=(a,b,p)=>{const t=Math.min(1,Math.max(0,(p-a)/(b-a)));return t*t*(3-2*t);};
function size(){if(!renderer||!root.value)return;const r=root.value.getBoundingClientRect();renderer.setSize(r.width,r.height,false);camera.aspect=r.width/Math.max(1,r.height);camera.updateProjectionMatrix();renderer.render(scene,camera);}
function down(e){if(props.progress>.15||props.reduced||!ready.value)return;drag={x:e.clientX,y:e.clientY,yaw,pitch};dragging.value=true;canvas.value.setPointerCapture(e.pointerId);}
function move(e){if(drag){yaw=drag.yaw+(e.clientX-drag.x)*.009;pitch=Math.max(-1.1,Math.min(1.1,drag.pitch+(e.clientY-drag.y)*.006));return;}if(!model||!raycaster||e.pointerType!=='mouse')return;const r=canvas.value.getBoundingClientRect();screenPoint.set((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1);raycaster.setFromCamera(screenPoint,camera);const hits=raycaster.intersectObject(model.glass);hover=hits.length?1:0;if(hits.length){const local=model.group.worldToLocal(hits[0].point.clone());model.hologramMaterial.uniforms.uPoint.value.set(local.x,local.y);}}
function up(){drag=null;dragging.value=false;}
function key(e){if(props.progress>.15)return;if(e.key==='ArrowLeft')yaw-=.3;else if(e.key==='ArrowRight')yaw+=.3;else if(e.key==='ArrowUp')pitch=Math.max(-1.1,pitch-.15);else if(e.key==='ArrowDown')pitch=Math.min(1.1,pitch+.15);else if(e.key==='Home'){yaw=-.23;pitch=.06;}else return;e.preventDefault();}
function loop(time){frame=0;if(destroyed||!renderer||!visible||document.hidden||props.reduced||props.progress>.78)return;if(time-last>24){last=time;const p=props.progress||0,approach=smooth(.08,.7,p),align=smooth(.03,.28,p);const targetYaw=Math.atan2(Math.sin(yaw),Math.cos(yaw))*(1-align),delta=targetYaw-model.group.rotation.y;model.group.rotation.y+=Math.atan2(Math.sin(delta),Math.cos(delta))*.12;model.group.rotation.x+=(pitch*(1-align)-model.group.rotation.x)*.12;model.group.position.y=Math.sin(time*.0005)*.025*(1-approach);camera.position.z=6.3-approach*4.6;camera.lookAt(0,0,0);model.hologramMaterial.uniforms.uTime.value=time*.001;visorHover+=(hover-visorHover)*.08;model.hologramMaterial.uniforms.uHover.value=visorHover*(1-smooth(.25,.55,p));renderer.render(scene,camera);}frame=requestAnimationFrame(loop);}
function sync(){cancelAnimationFrame(frame);frame=0;if(renderer&&!props.reduced&&visible&&!document.hidden&&props.progress<=.78)frame=requestAnimationFrame(loop);}
watch(()=>[props.progress>.78,props.reduced],sync);
onMounted(async()=>{if(props.reduced)return;try{const[three,{RoomEnvironment},{createPremiumHeadset}]=await Promise.all([import('three'),import('three/addons/environments/RoomEnvironment.js'),import('../utils/premiumHeadset.js')]);if(destroyed)return;THREE=three;renderer=new THREE.WebGLRenderer({canvas:canvas.value,alpha:true,antialias:true,powerPreference:'low-power'});renderer.setPixelRatio(Math.min(devicePixelRatio||1,1.5));renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(36,1,.08,30);camera.position.set(0,0,6.3);camera.lookAt(0,0,0);const generator=new THREE.PMREMGenerator(renderer),room=new RoomEnvironment();environment=generator.fromScene(room,.04);scene.environment=environment.texture;room.dispose();generator.dispose();scene.add(new THREE.HemisphereLight(0xc0e7ff,0x071321,1.4));const key=new THREE.DirectionalLight(0xb6e8ff,3.2);key.position.set(-3,4,5);scene.add(key);const rim=new THREE.DirectionalLight(0x4387ff,4);rim.position.set(3,2,-2);scene.add(rim);model=createPremiumHeadset();scene.add(model.group);raycaster=new THREE.Raycaster();screenPoint=new THREE.Vector2();size();ready.value=true;resize=new ResizeObserver(size);resize.observe(root.value);intersection=new IntersectionObserver(([e])=>{visible=e.isIntersecting;sync();});intersection.observe(root.value);document.addEventListener('visibilitychange',sync);sync();}catch(error){ready.value=false;renderer?.dispose();renderer=null;console.warn('Visual 3D indisponível; mantendo a imagem de apoio.',error);}});
onUnmounted(()=>{destroyed=true;cancelAnimationFrame(frame);resize?.disconnect();intersection?.disconnect();document.removeEventListener('visibilitychange',sync);model?.dispose();environment?.dispose();renderer?.dispose();});
</script>
<template><div ref="root" class="headset-scene" :class="{'mesh-ready':ready&&!reduced,dragging}"><img src="/images/vr-headset.png" alt="" width="1536" height="1024" class="headset-fallback" /><canvas ref="canvas" class="headset-canvas" :tabindex="ready&&progress<.15&&!reduced?0:-1" role="img" aria-label="Óculos de realidade virtual 3D. Arraste para girar; use as setas no teclado e Home para voltar à frente." @pointerdown="down" @pointermove="move" @pointerup="up" @pointercancel="up" @lostpointercapture="up" @pointerleave="hover=0" @keydown="key" /><p v-if="ready&&progress<.1" class="headset-hint">Arraste para explorar 360° <span aria-hidden="true">↔</span></p></div></template>
<style scoped>
.headset-scene{position:relative;width:min(68vw,960px);height:min(49vw,660px);}.headset-fallback{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;transition:opacity .5s;transform:scale(var(--headset-scale));pointer-events:none;}.headset-canvas{width:100%;height:100%;display:block;opacity:0;transition:opacity .5s;cursor:grab;touch-action:pan-y;pointer-events:auto;}.dragging .headset-canvas{cursor:grabbing;}.mesh-ready .headset-fallback{opacity:0;}.mesh-ready .headset-canvas{opacity:1;}.headset-hint{position:absolute;left:50%;bottom:7%;transform:translateX(-50%);white-space:nowrap;color:#89aebf;font:9px var(--font-mono);letter-spacing:.07em;pointer-events:none;}.headset-hint span{margin-left:14px;}@media(max-width:700px){.headset-scene{width:100vw;height:84vw;}.headset-hint{bottom:0;font-size:8px;}}
</style>
